import { describe, expect, it } from 'vitest'
import { renderHeaders } from '../../../../../deploy/bin/render-headers.ts'

const headers = {
  'Content-Security-Policy': "default-src 'none'; script-src 'self' 'wasm-unsafe-eval'",
  'X-Content-Type-Options': 'nosniff',
}

describe('renderHeaders', () => {
  it("serves the build's headers on its own path only, with the entry page revalidated and the rest immutable", () => {
    expect(renderHeaders('202610111205-abcdef0', { headers, entry: 'index.html' })).toBe(
      [
        '# Generated by deploy for build 202610111205-abcdef0 from its headers.json.',
        '@build_202610111205_abcdef0 path /builds/202610111205-abcdef0/*',
        'header @build_202610111205_abcdef0 {',
        `\tContent-Security-Policy "default-src 'none'; script-src 'self' 'wasm-unsafe-eval'"`,
        '\tX-Content-Type-Options "nosniff"',
        '}',
        '@build_202610111205_abcdef0_entry path /builds/202610111205-abcdef0/ /builds/202610111205-abcdef0/index.html',
        'header @build_202610111205_abcdef0_entry Cache-Control "no-cache"',
        '@build_202610111205_abcdef0_files {',
        '\tpath /builds/202610111205-abcdef0/*',
        '\tnot path /builds/202610111205-abcdef0/ /builds/202610111205-abcdef0/index.html',
        '}',
        'header @build_202610111205_abcdef0_files Cache-Control "public, max-age=31536000, immutable"',
        '',
      ].join('\n'),
    )
  })

  it('refuses anything that could break out of a header line into Caddy config', () => {
    const id = '202610111205-abcdef0'
    expect(() => renderHeaders(id, { headers: { 'X-A': 'a"b' }, entry: 'index.html' })).toThrow(/X-A/)
    expect(() => renderHeaders(id, { headers: { 'X-A': 'a\nb' }, entry: 'index.html' })).toThrow(/X-A/)
    expect(() => renderHeaders(id, { headers: { 'X-A': 'a}b' }, entry: 'index.html' })).toThrow(/X-A/)
    expect(() => renderHeaders(id, { headers: { 'X A': 'a' }, entry: 'index.html' })).toThrow(/X A/)
    expect(() => renderHeaders(id, { headers, entry: '../index.html' })).toThrow(/entry/)
    expect(() => renderHeaders('../etc', { headers, entry: 'index.html' })).toThrow(/build ID/)
  })
})
